/* Portraits peints (générés, originaux) — produit par make.py */
const PAINT={"Brigand": "data:image/webp;base64,", "Champignon sauteur": "data:image/webp;base64,", "Frelon des haies": "data:image/webp;base64,", "Gelée verte": "data:image/webp;base64,", "Luciole ardente": "data:image/webp;base64,", "Marcassin": "data:image/webp;base64,", "Rat des greniers": "data:image/webp;base64,", "Renard chapardeur": "data:image/webp;base64,", "Sanglier épineux": "data:image/webp;base64,", "cls_archere": "data:image/webp;base64,", "cls_lame": "data:image/webp;base64,", "cls_rempart": "data:image/webp;base64,", "Épouvantail grimaçant": "data:image/webp;base64,"};
for(const n in PAINT){if(n.startsWith("cls_"))continue;PORTRAIT[n]=`<img class="pimg" src="${PAINT[n]}" alt="" draggable="false">`}
{const _cm=classMed;classMed=function(c){const k=PAINT["cls_"+c];return k?`<span class="pmed"><img class="pimg" src="${k}" alt="" draggable="false"></span>`:_cm(c)}}
